 ctx.fillStyle='#799365';ctx.beginPath();ctx.arc(O.x,O.y,2.3,0,Math.PI*2);ctx.fill();ctx.font='8px system-ui';ctx.textAlign='left';ctx.fillStyle='#9fae92';ctx.fillText('0',O.x-9,O.y+13);
 for(const m of project.measures.filter(m=>m.view===view))dimension(m.a,m.b,measure(Math.hypot(m.b.u-m.a.u,m.b.v-m.a.v)),-17,'#597e8a');
