function zoom(f,x=cw/2,y=ch/2){const world=toWorld(x,y);paper.scale=Math.min(30,Math.max(.003,paper.scale*f));paper.ox=x-world.u*paper.scale;paper.oy=y+world.v*paper.scale;draw();}
canvas.addEventListener('wheel',e=>{e.preventDefault();const p=eventPoint(e);zoom(Math.exp(-e.deltaY*.001),p.x,p.y);},{passive:false});
$('#zoom-in').onclick=()=>zoom(1.25);$('#zoom-out').onclick=()=>zoom(.8);$('#fit2d').onclick=fit2d;$('#grid-size').onchange=draw;$('#snap').onchange=draw;
function fitAll(){fit2d();model?.fit();}
function openModal(title,body,footer=''){const modal=$('#modal');$('#modal-content').innerHTML=`<div class="modal-heading"><h2>${title}</h2><button class="icon-button" data-close aria-label="Fechar">${icon('close')}</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}`;if(!modal.open)modal.showModal();}
$('#modal').addEventListener('click',e=>{if(e.target.closest('[data-close]')||e.target===$('#modal'))$('#modal').close();});
function newModal(){openModal('Um novo começo.',`<p>Escolha uma base e dê as primeiras medidas. Você pode editar cada peça depois.</p><label class="form-field"><span>Nome do projeto</span><input id="new-name" class="text-input" maxlength="120" value="Meu novo móvel"></label><label class="form-field"><span>Começar com</span><select id="new-kind"><option value="blank">Papel em branco</option><option value="cabinet">Armário com divisórias</option><option value="desk">Bancada</option><option value="panel">Painel de parede</option></select></label><div class="property-grid">${field('Largura','new-w',1200,100,20000)}${field('Altura','new-h',900,100,20000)}${field('Profundidade','new-d',350,50,20000)}</div><p class="warning-text">O projeto atual fica salvo até você criar o novo. Baixe uma cópia para guardar vários projetos; Ctrl+Z também recupera o anterior nesta sessão.</p>`,`<button class="button" data-close>Cancelar</button><button class="button dark" id="create-project">Criar projeto ${icon('plus')}</button>`);$('#create-project').onclick=()=>{const vals=['new-w','new-h','new-d'].map(k=>inputValue($(`[data-prop="${k}"]`)));if(!vals.every((v,i)=>Number.isFinite(v)&&v>=(i===2?50:100)&&v<=20000)){toast('Confira as medidas antes de criar.');return;}const chosenUnit=unit(),name=$('#new-name').value.trim()||'Meu novo móvel',kind=$('#new-kind').value,t=Math.min(project.thickness,Math.min(...vals)/4);commit(()=>{project=createProject(kind,...vals,name,t);project.unit=chosenUnit;selected=project.pieces[0]?.id||null;},{fit:true});$('#modal').close();setTool(kind==='blank'?'line':'select');toast('Projeto criado. Vamos dar forma à sua ideia.');};}
$('#new-btn').onclick=newModal;
function addModal(){openModal('Adicionar uma peça',`<label class="form-field"><span>Nome da peça</span><input class="text-input" id="add-name" maxlength="120" value="Prateleira ${project.pieces.length+1}"></label><label class="form-field"><span>Orientação</span><select id="add-kind"><option value="horizontal">Horizontal · prateleira ou tampo</option><option value="vertical">Vertical · lateral ou divisória</option><option value="frontal">Frontal · fundo ou porta</option></select></label><div class="property-grid">${field('Largura','add-w',Math.min(600,project.w),.1,20000)}${field('Altura','add-h',project.thickness,.1,20000)}${field('Profundidade','add-d',project.d,.1,20000)}</div><p>A peça começa na origem (0, 0, 0). Arraste no desenho ou digite a posição nas propriedades.</p>`,`<button class="button" data-close>Cancelar</button><button class="button dark" id="confirm-add">Adicionar peça</button>`);$('#add-kind').onchange=e=>{const vals=e.target.value==='vertical'?[project.thickness,project.h,project.d]:e.target.value==='frontal'?[project.w,project.h,project.thickness]:[Math.min(600,project.w),project.thickness,project.d];['add-w','add-h','add-d'].forEach((k,i)=>$(`[data-prop="${k}"]`).value=fixed(vals[i]/factor()));};$('#confirm-add').onclick=()=>{const dims=['add-w','add-h','add-d'].map(k=>inputValue($(`[data-prop="${k}"]`)));if(!dims.every(v=>Number.isFinite(v)&&v>0&&v<=20000)){toast(`Informe dimensões maiores que zero, até ${measure(20000)}.`);return;}commit(()=>{const p=piece($('#add-name').value.trim()||'Nova peça',0,0,0,...dims);project.pieces.push(p);selected=p.id;});$('#modal').close();setTool('select');};}
$('#add-btn').onclick=addModal;
$('#rename-project').onclick=()=>{openModal('Nome do projeto',`<input class="text-input" id="rename-input" maxlength="120" value="${esc(project.name)}" aria-label="Nome do projeto">`,`<button class="button" data-close>Cancelar</button><button class="button dark" id="confirm-rename">Salvar nome</button>`);$('#confirm-rename').onclick=()=>{const name=$('#rename-input').value.trim();if(!name)return;commit(()=>project.name=name);$('#modal').close();};};
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
const slug=()=>project.name.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9-]/g,'-').toLowerCase().slice(0,80)||'meu-movel';
function exportProject(){download(new Blob([JSON.stringify(project,null,2)],{type:'application/json'}),slug()+'.json');toast('Projeto baixado. Use Abrir para continuar em outro dispositivo.');}
$('#export-btn').onclick=exportProject;$('#import-btn').onclick=()=>$('#import-file').click();$('#import-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>5e6)throw new Error('O arquivo deve ter até 5 MB.');const p=validateProject(JSON.parse(await f.text()));delete p.presetId;commit(()=>{project=p;project.unit??='cm';selected=p.room?.active?null:p.pieces[0]?.id||null;},{fit:true});toast('Projeto aberto com sucesso.');}catch(err){toast(err instanceof SyntaxError?'Este arquivo não é um projeto JSON válido.':err.message);}e.target.value='';};
function csvExport(){const quote=v=>'"'+String(v).replace(/"/g,'""')+'"';const safeName=v=>/^[=+@\-\t\r]/.test(v)?"'"+v:v;const rows=[['Peça',`Largura (${unit()})`,`Altura (${unit()})`,`Profundidade (${unit()})`,'Material','Área de chapa (m²)'],...project.pieces.map(p=>[safeName(p.name),String(fixed(p.w/factor())).replace('.',','),String(fixed(p.h/factor())).replace('.',','),String(fixed(p.d/factor())).replace('.',','),MATERIALS[p.material].name,area([p]).toFixed(4).replace('.',',')])];download(new Blob(['\ufeff'+rows.map(r=>r.map(quote).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}),slug()+'-pecas.csv');}
function cutList(){openModal('Cada peça, na medida.',`<p>${esc(project.name)} · ${project.pieces.length} peças · Todas as medidas em ${unit()==='cm'?'centímetros':'milímetros'}</p>${project.designNotes?`<p class="measure-notice">${esc(project.designNotes)}</p>`:''}<div class="modal-scroll"><table class="cut-table"><thead><tr><th>Peça</th><th>L × A × P (${unit()})</th><th>Acabamento</th></tr></thead><tbody>${project.pieces.map(p=>`<tr><td>${esc(p.name)}</td><td>${num(p.w/factor())} × ${num(p.h/factor())} × ${num(p.d/factor())}</td><td>${MATERIALS[p.material].name}</td></tr>`).join('')||'<tr><td colspan="3">Seu projeto ainda não tem peças.</td></tr>'}</tbody></table></div><div class="cut-meta"><span>Área teórica de chapas</span><strong>${num(area(project.pieces))} m²</strong></div><p class="warning-text">A área usa as duas maiores dimensões de cada peça. Não inclui perdas, fita de borda ou espessura do corte. Esta lista não é um plano de corte otimizado. Confira encaixes, folgas e fixação antes de fabricar.</p>`,`<button class="button" data-close>Fechar</button><button class="button dark" id="download-csv">${icon('download')}Baixar lista CSV</button>`);$('#download-csv').onclick=csvExport;}
$('#cutlist-btn').onclick=cutList;
$('#help-btn').onclick=()=>openModal('Do papel ao seu móvel.',`<div class="help-step"><span>1</span><div><h3>Desenhe na grade</h3><p>Escolha <b>Linha</b> e arraste. Na vista Frente, uma linha vira uma chapa com a espessura padrão e a profundidade de referência. O traço marca o eixo central da chapa. Segure <span class="key">Alt</span> para desenhar inclinado. <b>Painel</b> cria uma chapa retangular na vista escolhida.</p></div></div><div class="help-step"><span>2</span><div><h3>Acerte cada milímetro</h3><p>Arraste as alças nos cantos e nas bordas para redimensionar. Alt desativa o encaixe durante o arraste; Shift mantém a proporção nos cantos. Selecione uma peça e edite largura, altura, profundidade, posição e rotação. X é horizontal, Y é altura e Z é profundidade. As vistas Frente, Superior e Lateral ajudam a posicionar cada parte.</p></div></div><div class="help-step"><span>3</span><div><h3>Explore em 3D</h3><p>Arraste para girar, role para aproximar e use o botão direito para deslocar a câmera. Toque numa peça para selecioná-la. Use a vista explodida para examinar a montagem.</p></div></div><div class="help-step"><span>4</span><div><h3>Guarde seu desenho</h3><p>Seu projeto é salvo automaticamente neste navegador. <b>Salvar projeto</b> baixa um arquivo JSON que você pode reabrir. A <b>Lista de peças</b> exporta as medidas em CSV.</p></div></div><p><span class="key">V</span> Selecionar · <span class="key">L</span> Linha · <span class="key">R</span> Painel · <span class="key">M</span> Medir · <span class="key">H</span> Mover papel · <span class="key">F</span> Enquadrar · <span class="key">Ctrl+Z</span> Desfazer · <span class="key">Ctrl+D</span> Duplicar · <span class="key">Delete</span> Excluir</p><p><b>Planejar quarto</b> permite definir o ambiente e posicionar móveis pela planta. Escolha cm ou mm no seletor de unidades; as cotas e os campos acompanham a escolha.</p><p>Os limites de referência orientam o desenho; alterar esses valores não redimensiona peças já criadas. No celular, toque no nome do projeto para criar, abrir ou acessar a lista.</p>`,`<button class="button dark" data-close>Vamos criar ${icon('line')}</button>`);
document.addEventListener('keydown',e=>{if($('#modal').open||['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName))return;if(e.ctrlKey||e.metaKey){if(e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo();}if(e.key.toLowerCase()==='y'){e.preventDefault();redo();}if(e.key.toLowerCase()==='d'){e.preventDefault();duplicate();}if(e.key.toLowerCase()==='s'){e.preventDefault();exportProject();}return;}if(room?.active&&e.key.toLowerCase()==='r'){room.rotateSelected();return;}const map={v:'select',l:'line',r:'rect',m:'measure',h:'pan'};if(map[e.key.toLowerCase()])setTool(map[e.key.toLowerCase()]);if(e.key.toLowerCase()==='f')fitAll();if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();removePiece();}if(e.key==='Escape'){cancelGesture();setTool('select');}});
